/* Present complete source frames. Image concepts never imply video approval. */
(()=>{
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const hero=s=>s.sequence?.heroIndex??1;
 const others=s=>[0,1,2,3].filter(i=>i!==hero(s));
 const picture=(s,i,base='',cls='',small=false)=>{const f=s.sequence?.frames?.[i];return f?`<img class="${cls}" src="${esc(base+(small?f.thumbnail||f.src:f.src))}" alt="${esc(f.alt||s.name+' · '+f.label)}" width="${f.width}" height="${f.height}" loading="lazy" decoding="async">`:''};
 function strip(s,base=''){
  if(!s.sequence?.frames?.length)return '';
  return `<div class="sequence-strip" aria-label="Momentos da sequência">${others(s).map((i,n)=>`<button type="button" data-sequence="${esc(s.id)}" data-frame-index="${i}" aria-label="Ampliar ${esc(s.sequence.frames[i].label)} de ${esc(s.name)}">${picture(s,i,base,'',true)}<span>${String(i+1).padStart(2,'0')}</span></button>`).join('')}</div>`;
 }
 function sequence(s,base=''){
  if(!s.sequence?.frames?.length)return '';
  return `<section class="film-sheet" aria-label="Sequência visual de ${esc(s.name)}"><figure class="film-hero"><button class="frame-expand" data-sequence="${esc(s.id)}" data-frame-index="${hero(s)}" aria-label="Ampliar quadro principal">${picture(s,hero(s),base)}</button><figcaption>Quadro principal · ${String(hero(s)+1).padStart(2,'0')} · ${esc(s.sequence.frames[hero(s)].label.toLowerCase())}</figcaption></figure><div class="film-story"><h3>Como a história evolui</h3><p class="small">Siga a numeração 01 → 04, incluindo o quadro principal.</p><p class="mobile-sequence-hint">Deslize para ver os momentos →</p><div class="film-steps">${others(s).map((i,n)=>{const f=s.sequence.frames[i];return `<figure><button class="frame-expand" data-sequence="${esc(s.id)}" data-frame-index="${i}" aria-label="Ampliar ${esc(f.label)}">${picture(s,i,base)}</button><figcaption><strong>${String(i+1).padStart(2,'0')} · ${esc(f.label)}</strong><p>${esc(f.caption||f.action)}</p></figcaption></figure>`}).join('')}</div><p class="film-sound">♪ ${esc(s.sequence.audio||'Voz, trilha e efeitos definidos pela direção do estilo.')}</p></div></section><p class="concept-note">Sequência conceitual de quatro quadros. Movimento, texto e fidelidade precisam ser conferidos na amostra em vídeo.</p>`;
 }
 function card(s,{base='',selected=false,favorite=false,compared=false,icon,imageStyle,previewMedia}){
  return `<article class="card${selected?' is-selected':''}" data-style-id="${esc(s.id)}"><button type="button" class="style-cover" data-detail="${esc(s.id)}" aria-label="Ver direção: ${esc(s.name)}"><span class="preview" style="${imageStyle(s)}">${previewMedia(s)}</span></button><div class="card-body"><div class="card-title-row"><h3><button class="card-title" data-detail="${esc(s.id)}">${esc(s.name)}</button></h3><button class="favorite" data-fav="${esc(s.id)}" aria-label="${favorite?'Remover dos':'Adicionar aos'} favoritos: ${esc(s.name)}" aria-pressed="${favorite}">${icon('heart')}</button></div><div class="card-meta"><span>${s.sequence?'▧ 4 quadros':'Estudo visual'}</span>${s.preview?'<span class="video-badge" title="Amostra anterior; aprovação pendente">▷ Com vídeo</span>':''}</div>${strip(s,base)}<div class="card-actions"><button class="add-direction${selected?' chosen':''}" data-choose="${esc(s.id)}" aria-pressed="${selected}">${selected?'✓ Selecionado':'+ Escolher'}</button><label class="compare-toggle"><input type="checkbox" data-compare="${esc(s.id)}" ${compared?'checked':''}>Comparar</label></div></div></article>`;
 }
 function detail(s,{base='',requirementsHtml,readinessHtml}){
  return `<header class="direction-header"><p class="eyebrow">${esc(s.familyName)}</p><h2>${esc(s.name)}</h2><p>${esc(s.signature)}</p><div class="actions"><button class="primary" data-choose="${esc(s.id)}">Usar como principal</button><button class="outline" data-add="${esc(s.id)}">Combinar com minha escolha</button><button class="outline" data-frame="${esc(s.id)}">↓ Baixar quadro principal</button><button class="outline" data-board="${esc(s.id)}">↓ Baixar sequência</button></div></header>${sequence(s,base)}${s.advertising?`<section class="direction-use"><h3>Anúncio com história e voz</h3><p><strong>${esc(s.advertising.frameworkMeaning)}</strong> · 30–45 s sugeridos</p><p>Narração em português + legendas editáveis + chamada final.</p><p>Gancho: ${esc(s.advertising.hook)}</p><p>Fechamento: <strong>${esc(s.advertising.cta)}</strong></p><p class="small">O áudio será produzido após a pré-produção aprovada. Estas imagens não têm som.</p></section>`:''}<div class="direction-use"><h3>Quando usar</h3><p>${esc(s.uses)}</p><p class="small">Exemplo fictício: ${esc(s.sequence?.theme||s.exampleTopic)}. Complexidade indicativa: ${esc(s.complexity)}.</p></div>${s.preview?`<details class="direction-disclosure"><summary>Ver amostra anterior em vídeo</summary><p class="small">Esta amostra é anterior à revisão das imagens. Ela não reproduz necessariamente a nova sequência e continua com aprovação pendente.</p><video controls playsinline preload="none" poster="${esc(base+s.preview.poster)}" src="${esc(base+s.preview.url)}" aria-label="Amostra de ${esc(s.name)}"></video><p class="small">${esc(s.preview.note)}</p></details>`:''}<details class="direction-disclosure"><summary>Movimento, som e recursos de produção</summary><h3>Movimento proposto</h3><p>${esc(s.motion)}</p><h3>Recursos</h3><ul>${s.resources.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Voz, trilha e efeitos</h3><p>${esc(s.audio?.voice)}</p><p>${esc(s.audio?.music)}</p><p>${esc(s.audio?.sfx)}</p><h3>O que demonstrar na amostra</h3><p>${esc(s.proof)}</p></details><details class="direction-disclosure"><summary>Materiais, ferramentas e fidelidade</summary>${requirementsHtml(s)}<p>${esc(s.requirements)}</p><p>${esc(s.preset.productFidelity)}</p>${readinessHtml(s)}<p class="small">${esc(s.note)}</p></details>`;
 }
 window.AtlasViews={esc,picture,strip,sequence,card,detail};
})();
